IF OBJECT_ID('[${flyway:defaultSchema}].[vwCommunicationActivities]', 'V') IS NOT NULL
    DROP VIEW [${flyway:defaultSchema}].[vwCommunicationActivities];
GO

CREATE VIEW [${flyway:defaultSchema}].[vwCommunicationActivities]
AS
SELECT
    c.*,
    MJCommunicationLog_CommunicationLogID.[MessageDate] AS [CommunicationLog],
    MJCommunicationSender_CommunicationSenderID.[Name] AS [CommunicationSender],
    MJCommunicationProvider_CommunicationProviderID.[Name] AS [CommunicationProvider]
FROM
    [${flyway:defaultSchema}].[CommunicationActivity] AS c
LEFT OUTER JOIN
    [${flyway:defaultSchema}].[CommunicationLog] AS MJCommunicationLog_CommunicationLogID
  ON
    [c].[CommunicationLogID] = MJCommunicationLog_CommunicationLogID.[ID]
LEFT OUTER JOIN
    [${flyway:defaultSchema}].[CommunicationSender] AS MJCommunicationSender_CommunicationSenderID
  ON
    [c].[CommunicationSenderID] = MJCommunicationSender_CommunicationSenderID.[ID]
INNER JOIN
    [${flyway:defaultSchema}].[CommunicationProvider] AS MJCommunicationProvider_CommunicationProviderID
  ON
    [c].[CommunicationProviderID] = MJCommunicationProvider_CommunicationProviderID.[ID]
GO
